        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v)
        elif isinstance(obj, list):
            for item in obj:
                collect_values(item)
        else:
            all_values.append(obj)
    collect_values(data)
    value_counts = Counter(all_values)
    return {"data": data, "value_counts": value_counts}

